/* BESTIAIRE — données : reptiles, amphibiens et poissons (suite) */
window.ANIMAUX = (window.ANIMAUX || []).concat([

/* ============ REPTILES ============ */

{id:"tortue-galapagos",nom:"Tortue géante des Galápagos",sci:"Chelonoidis niger",emo:"🐢",gr:"Reptile",ord:"Testudines",fam:"Testudinidés",bio:"desert",
hab:"Îles volcaniques arides et hauts plateaux",rep:"Galápagos",taille:"1,2 à 1,8 m",poidsKg:250,vit:0.3,vie:150,
reg:"Herbivore",uicn:"VU",rar:5,
res:"Elle a donné à Darwin l'une de ses premières intuitions, avant d'être presque exterminée par les navires qui l'emportaient vivante en cale.",
f:[["Le gouverneur des Galápagos avait dit à Darwin qu'on pouvait reconnaître l'île d'origine d'une tortue à la forme de sa carapace. Darwin n'y a d'abord pas prêté attention — il a même mangé plusieurs spécimens pendant le voyage. C'est en rentrant, en réexaminant ses notes, qu'il a compris ce que cela signifiait.","expert"],
["Deux formes de carapace correspondent à deux régimes : « en dôme » sur les îles humides où l'herbe est au sol, « en selle » — échancrée sur la nuque — sur les îles arides, ce qui permet de lever le cou vers les cactus. Une même lignée, deux solutions selon l'île.","pointu"],
["Elle survit un an sans boire ni manger, en stockant l'eau dans sa vessie. C'est précisément ce qui l'a condamnée : les baleiniers en entassaient des centaines vivantes dans leurs cales comme viande fraîche autonome. On estime à plus de 100 000 le nombre emporté au XIXᵉ siècle.","expert"],
["Un mâle de l'île Española nommé Diego, rapatrié d'un zoo américain, a engendré à lui seul près de 40 % des 2 000 tortues qui repeuplent aujourd'hui son île. Rendu à la vie sauvage en 2020 après cinquante ans de reproduction, il a sauvé une population tombée à 14 individus.","pointu"],
["Lonesome George, dernier de la sous-espèce de l'île Pinta, est mort en 2012 sans descendance. Sa dépouille naturalisée est exposée comme un avertissement.","base"]],
v:[["Spéciation insulaire","Divergence de populations isolées sur des îles voisines. Chaque île impose ses contraintes ; les formes s'écartent jusqu'à devenir des sous-espèces, puis parfois des espèces."]],
q:[["À quoi correspond la carapace « en selle » de certaines tortues des Galápagos ?",["À un mâle dominant","À une île aride où il faut lever le cou vers les cactus","À une maladie","À un âge avancé"],1,"Deux formes, deux régimes, une seule lignée : l'intuition de départ de Darwin."],
["Pourquoi les baleiniers en ont-ils emporté plus de 100 000 ?",["Pour leur carapace","Elles survivent un an sans manger : de la viande fraîche autonome en cale","Pour leur huile","Pour les vendre en Europe"],1,"Leur meilleure adaptation à l'aridité est devenue leur condamnation."]],
d:["retour","extremes","taxo"]},

{id:"anaconda-vert",nom:"Anaconda vert",sci:"Eunectes murinus",emo:"🐍",gr:"Reptile",ord:"Squamata",fam:"Boïdés",bio:"riviere",
hab:"Marécages et rivières lentes",rep:"Bassin amazonien",taille:"4 à 6 m",poidsKg:90,vit:16,vie:25,
reg:"Carnivore",uicn:"LC",rar:4,
res:"Le serpent le plus lourd du monde. Il ne broie pas ses proies : il leur coupe l'irrigation sanguine.",
f:[["Le python réticulé est plus long, mais l'anaconda est bien plus massif : jusqu'à 100 kg pour une grosse femelle, contre une trentaine pour un python de même longueur.","base"],
["On a longtemps dit qu'un constricteur tue par étouffement ou en broyant les os. Des mesures de 2015 ont montré autre chose : la pression exercée dépasse celle du sang artériel, l'irrigation du cerveau et du cœur s'arrête, et la proie perd connaissance en quelques secondes. C'est un arrêt circulatoire, beaucoup plus rapide qu'une asphyxie.","expert"],
["Ses yeux et ses narines sont sur le dessus du crâne : il flotte immobile, entièrement immergé sauf ces trois points, pendant des heures.","base"],
["La femelle est jusqu'à cinq fois plus lourde que le mâle — l'un des plus forts dimorphismes en faveur des femelles chez les vertébrés terrestres. Lors de la reproduction, jusqu'à douze mâles s'enroulent autour d'elle en une « boule de reproduction » qui peut durer des semaines.","pointu"],
["Il est ovovivipare : les œufs éclosent à l'intérieur de la mère, qui met bas de 20 à 40 petits déjà autonomes. Un avantage net en milieu inondé, où un nid serait noyé.","pointu"]],
v:[["Ovoviviparité","Les œufs se développent et éclosent à l'intérieur du corps de la mère, sans placenta. Intermédiaire entre la ponte et la gestation véritable ; fréquente chez les serpents des milieux froids ou humides."]],
q:[["Comment un constricteur tue-t-il réellement sa proie ?",["Par étouffement","En arrêtant la circulation sanguine vers le cerveau","En broyant les os","Par un venin"],1,"Mesuré en 2015 : la pression dépasse celle du sang artériel, et la proie s'éteint en quelques secondes."],
["Qu'est-ce que l'ovoviviparité ?",["Pondre des œufs mous","Les œufs éclosent à l'intérieur de la mère","Pondre dans l'eau","Couver les œufs"],1,"Un avantage net en milieu inondé, où un nid serait noyé."]],
d:["records"]},

{id:"vipere-gabon",nom:"Vipère du Gabon",sci:"Bitis gabonica",emo:"🐍",gr:"Reptile",ord:"Squamata",fam:"Vipéridés",bio:"jungle",
hab:"Litière de forêt tropicale",rep:"Afrique centrale et de l'Ouest",taille:"1,2 à 1,8 m",poidsKg:8,vit:null,vie:20,
reg:"Carnivore",uicn:"LC",rar:4,
res:"Les crochets les plus longs du monde, sur le serpent le plus lourd d'Afrique — et l'un des camouflages les plus efficaces jamais mesurés.",
f:[["Ses crochets atteignent 5 cm, un record absolu chez les serpents. Repliés contre le palais au repos, ils basculent vers l'avant au moment de la morsure.","base"],
["Ses motifs géométriques beiges, bruns et violacés semblent voyants sur une photo. Posés sur la litière de feuilles mortes, ils deviennent invisibles : c'est de la coloration disruptive, qui décompose le corps en formes séparées au lieu d'imiter le fond.","pointu"],
["Elle ne fuit pas et ne prévient pas. Elle reste immobile des jours au même endroit, ce qui explique la plupart des morsures : on lui marche dessus. Sa frappe est pourtant l'une des plus rapides mesurées chez un serpent, en moins de 0,2 seconde.","pointu"],
["Contrairement à presque tous les serpents, elle ne lâche pas sa proie après la morsure : elle la maintient jusqu'à ce que le venin agisse. Avec 5 à 7 ml injectés par morsure, elle délivre l'un des plus gros volumes de venin du monde.","expert"],
["Son venin est surtout cytotoxique : il détruit les tissus au point d'injection. Sans soins, les séquelles sont massives même quand la victime survit — ce qui rappelle qu'un venin ne se juge pas seulement à sa létalité.","expert"]],
v:[["Cytotoxine","Toxine qui détruit les cellules et les tissus au point d'injection, provoquant nécrose et gonflement. Contrairement aux neurotoxines, elle tue rarement vite — mais mutile souvent."]],
q:[["Quelle est la longueur des crochets de la vipère du Gabon ?",["1 cm","2,5 cm","5 cm","10 cm"],2,"Un record absolu chez les serpents."],
["Pourquoi son motif voyant la rend-il invisible au sol ?",["Il imite exactement les feuilles","Il décompose sa silhouette en formes séparées","Il reflète la lumière","Il change de couleur"],1,"De la coloration disruptive, comme les rayures du tigre."]],
d:["camouflage","venins","records"]},

{id:"serpent-volant",nom:"Serpent volant du paradis",sci:"Chrysopelea paradisi",emo:"🐍",gr:"Reptile",ord:"Squamata",fam:"Colubridés",bio:"jungle",
hab:"Canopée",rep:"Asie du Sud-Est",taille:"1 à 1,2 m",poidsKg:0.1,vit:35,vie:12,
reg:"Carnivore",uicn:"LC",rar:5,
res:"Un serpent sans membres, sans ailes et sans membrane, qui plane sur 25 mètres en se transformant lui-même en aile.",
f:[["Il se lance d'une branche en forme de J, puis aplatit tout son corps en écartant ses côtes : sa section passe d'un cercle à un demi-disque concave, qui se comporte comme un profil d'aile.","base"],
["Il ne plane pas en ligne droite : il ondule en l'air, à environ un cycle par seconde. Une étude de 2020 a montré que cette ondulation n'est pas un réflexe de nage inutile — elle stabilise le vol. Des simulations sans ondulation font basculer et tomber l'animal. Il se stabilise en bougeant.","expert"],
["Il parcourt jusqu'à 25 m depuis 10 m de hauteur, et corrige sa trajectoire en vol pour viser un tronc précis.","pointu"],
["Cinq espèces de serpents planent ainsi, et aucune n'a la moindre membrane. Ils sont les seuls vertébrés planeurs à ne pas utiliser de surface déployée : leur corps est l'aile.","pointu"],
["Il est légèrement venimeux, avec des crochets situés à l'arrière de la mâchoire. Sans danger pour l'humain, mais efficace sur les lézards.","base"]],
v:[["Vol plané","Descente contrôlée où une surface convertit la chute en distance parcourue. Il est apparu indépendamment chez des écureuils, des lézards, des grenouilles, des poissons, des fourmis et des serpents."]],
q:[["Comment le serpent volant crée-t-il sa portance ?",["Avec une membrane","En aplatissant son corps en profil d'aile par écartement des côtes","Avec sa queue","Il ne plane pas vraiment"],1,"Sa section passe du cercle au demi-disque concave."],
["À quoi sert son ondulation en vol ?",["À avancer","À stabiliser le vol","À viser","À ralentir"],1,"Les simulations sans ondulation font basculer l'animal."]],
d:["records","convergence"]},

{id:"basilic-vert",nom:"Basilic vert",sci:"Basiliscus plumifrons",emo:"🦎",gr:"Reptile",ord:"Squamata",fam:"Corytophanidés",bio:"riviere",
hab:"Berges de rivières forestières",rep:"Amérique centrale",taille:"70 à 90 cm avec la queue",poidsKg:0.2,vit:11,vie:8,
reg:"Omnivore",uicn:"LC",rar:3,
res:"Il court sur l'eau. Ce n'est pas une figure de style : c'est un problème de physique qu'il résout à chaque foulée.",
f:[["Poursuivi, il se dresse sur ses pattes arrière et traverse jusqu'à 20 m de surface d'eau à environ 1,5 m par seconde, avant de couler et de nager.","base"],
["Chaque foulée se décompose en trois temps : la patte frappe la surface, ce qui crée une cavité d'air ; elle pousse dans cette cavité avant qu'elle ne se referme ; puis elle est retirée assez vite pour ne pas être aspirée. C'est la vitesse de retrait, plus que la frappe, qui fait tenir l'animal.","expert"],
["Des mesures ont montré qu'un humain adulte devrait courir à plus de 100 km/h et développer une puissance musculaire environ quinze fois supérieure à la sienne pour en faire autant. Ce n'est pas une question de technique : c'est une limite d'échelle.","expert"],
["Ses longs doigts arrière portent des franges de peau qui se déploient à l'impact et se replient au retrait — une palme escamotable.","pointu"],
["Son nom vient du basilic des bestiaires médiévaux, ce monstre qui tuait du regard. Il ne tue personne ; en anglais, on l'appelle plutôt le « lézard Jésus-Christ ».","base"]],
v:[["Contrainte d'échelle","Les forces ne varient pas toutes de la même façon avec la taille. La tension superficielle et la traînée dominent chez les petits animaux ; le poids domine chez les grands. Beaucoup d'exploits sont réservés à une taille donnée."]],
q:[["Quel est le geste décisif pour courir sur l'eau ?",["Frapper très fort","Retirer la patte avant que la cavité ne se referme","Courir en ligne droite","Battre la queue"],1,"C'est la vitesse de retrait qui empêche l'aspiration."],
["Pourquoi un humain ne peut-il pas en faire autant ?",["Il n'a pas les bons pieds","C'est une limite d'échelle : il faudrait 15 fois plus de puissance","Il est trop lourd de peu","Il ne sait pas s'y prendre"],1,"Les forces en jeu ne changent pas proportionnellement à la taille."]],
d:["records","extremes"]},

{id:"moloch",nom:"Moloch hérissé",sci:"Moloch horridus",emo:"🦎",gr:"Reptile",ord:"Squamata",fam:"Agamidés",bio:"desert",
hab:"Déserts de sable et de spinifex",rep:"Australie centrale et occidentale",taille:"20 cm",poidsKg:0.09,vit:null,vie:16,
reg:"Insectivore",uicn:"LC",rar:4,
res:"Il boit avec ses pieds. Sa peau est un réseau de capillaires qui conduit l'eau jusqu'à sa bouche, contre la gravité.",
f:[["Sa peau est parcourue de micro-canaux en réseau, ouverts entre les écailles. Par capillarité, l'eau qui touche n'importe quel point du corps circule jusqu'aux commissures de la bouche — y compris vers le haut. Il lui suffit de poser une patte sur du sable humide.","expert"],
["Il récolte aussi la rosée qui se condense sur lui la nuit et l'humidité du sable qu'il se jette sur le dos. Dans un désert sans point d'eau, il boit sans jamais trouver de flaque.","pointu"],
["Il ne mange que des fourmis, à raison de 600 à 3 000 par repas, attrapées une par une à la langue à un rythme d'environ 45 par minute.","base"],
["Il porte une fausse tête sur la nuque : une bosse épineuse. Menacé, il baisse la vraie tête entre ses pattes avant et présente le leurre au prédateur.","pointu"],
["Sa démarche saccadée, avec des arrêts et des balancements, imite une feuille agitée par le vent et brouille sa détection par les prédateurs qui repèrent le mouvement.","pointu"]],
v:[["Capillarité","Montée spontanée d'un liquide dans un canal très fin, sous l'effet des forces d'adhésion. C'est ce qui fait grimper l'eau dans une éponge — ou dans la peau du moloch."]],
q:[["Comment le moloch boit-il ?",["Par sa langue uniquement","L'eau circule dans les canaux de sa peau jusqu'à sa bouche","Il absorbe l'eau par le ventre","Il ne boit jamais"],1,"Par capillarité, y compris contre la gravité — il lui suffit de poser une patte sur du sable humide."],
["Qu'est-ce que la bosse sur sa nuque ?",["Une réserve de graisse","Une fausse tête servant de leurre","Un organe sensoriel","Une glande à venin"],1,"Il cache la vraie tête entre ses pattes et présente le leurre."]],
d:["extremes","camouflage"]},

{id:"gavial",nom:"Gavial du Gange",sci:"Gavialis gangeticus",emo:"🐊",gr:"Reptile",ord:"Crocodilia",fam:"Gavialidés",bio:"riviere",
hab:"Grands fleuves à courant rapide",rep:"Inde, Népal",taille:"3,5 à 6 m",poidsKg:200,vit:null,vie:60,
reg:"Piscivore",uicn:"CR",rar:5,
res:"Un crocodilien qui a poussé la spécialisation au poisson jusqu'à devenir incapable de manger autre chose — et incapable de marcher.",
f:[["Son museau est si fin et si long qu'il fend l'eau presque sans résistance. Il chasse d'un balayage latéral fulgurant de la tête, et ses 110 dents fines et entrecroisées retiennent le poisson comme une nasse.","base"],
["Cette finesse a un prix : sa mâchoire ne supporterait pas les contraintes d'une proie qui se débat. Il ne peut pas s'attaquer à de grands animaux. Aucune attaque de gavial sur un humain vivant n'est documentée.","pointu"],
["Ses pattes ne peuvent plus soutenir son poids à terre : contrairement aux autres crocodiliens, un gavial adulte ne peut pas marcher haut sur ses membres. Il se traîne sur le ventre et ne s'éloigne jamais de l'eau.","expert"],
["Le mâle adulte porte au bout du museau un renflement bulbeux, le ghara — « pot » en hindi. Il transforme ses sifflements en bourdonnements portant loin et sert de signal visuel. C'est le seul crocodilien à présenter un dimorphisme sexuel aussi net.","pointu"],
["Il en restait moins de 200 adultes reproducteurs dans les années 2000. Un vaste programme de collecte d'œufs et de relâchers a fait remonter la population à environ 650. Le gavial reste l'un des grands vertébrés les plus menacés de la planète.","expert"]],
v:[["Spécialisation","Adaptation poussée à une ressource ou un milieu. Elle rend très efficace tant que les conditions durent, et très vulnérable dès qu'elles changent."]],
q:[["Pourquoi le gavial ne s'attaque-t-il pas à de grandes proies ?",["Il est trop lent","Son museau fin ne supporterait pas les contraintes","Il n'a pas de dents","Il n'a pas faim"],1,"Aucune attaque documentée sur un humain vivant."],
["Qu'est-ce que le ghara ?",["Une dent","Un renflement au bout du museau du mâle","Une glande à sel","Une écaille dorsale"],1,"Il amplifie ses sons et signale son statut — un dimorphisme unique chez les crocodiliens."]],
d:["retour","taxo"]},

{id:"serpent-tentacule",nom:"Serpent tentaculé",sci:"Erpeton tentaculatum",emo:"🐍",gr:"Reptile",ord:"Squamata",fam:"Homalopsidés",bio:"riviere",
hab:"Eaux stagnantes et rizières",rep:"Asie du Sud-Est",taille:"50 à 90 cm",poidsKg:0.2,vit:null,vie:15,
reg:"Piscivore",uicn:"LC",rar:5,
res:"Il ne poursuit pas les poissons : il les fait fuir dans sa gueule, en exploitant un réflexe qu'ils ne peuvent pas désobéir.",
f:[["Il est le seul serpent au monde à porter deux tentacules sur le museau. Ce sont des organes sensoriels qui détectent les mouvements de l'eau : il chasse dans une eau opaque, sans voir sa proie.","pointu"],
["Un poisson effrayé déclenche une fuite réflexe en C, déclenchée par un neurone géant et impossible à annuler : il se plie en C et part à l'opposé du danger, en quelques millisecondes.","base"],
["Le serpent se met en J, puis provoque une secousse de son corps du côté opposé à sa tête. Le poisson exécute son réflexe et fuit… droit vers la gueule, qui l'attendait déjà. Le serpent commence son mouvement d'attaque avant même que le poisson n'ait bougé : il ne réagit pas, il prédit.","expert"],
["Ce n'est pas de l'apprentissage : des serpents nouveau-nés, sans aucune expérience, exécutent la manœuvre parfaitement dès leur première chasse. La prédiction est câblée.","expert"],
["Il reste des heures parfaitement immobile, en forme de J, et sa peau se couvre d'algues — un camouflage vivant.","base"]],
v:[["Réflexe en C","Fuite d'urgence des poissons, déclenchée par les cellules de Mauthner. Extrêmement rapide, mais stéréotypée : sa prévisibilité est exactement ce que le serpent tentaculé exploite."]],
q:[["Comment le serpent tentaculé capture-t-il un poisson ?",["Il le poursuit","Il déclenche son réflexe de fuite pour l'envoyer vers sa gueule","Il l'empoisonne","Il l'aspire"],1,"Il attaque avant même que le poisson n'ait bougé : il prédit sa trajectoire."],
["Ce comportement est-il appris ?",["Oui, avec l'expérience","Non : les nouveau-nés le réussissent dès la première chasse","Il est enseigné par la mère","Il n'apparaît qu'à l'âge adulte"],1,"La prédiction est câblée, pas acquise."]],
d:["sens","camouflage","records"]},

{id:"tortue-alligator",nom:"Tortue alligator",sci:"Macrochelys temminckii",emo:"🐢",gr:"Reptile",ord:"Testudines",fam:"Chélydridés",bio:"riviere",
hab:"Fonds vaseux de rivières et bayous",rep:"Sud-est des États-Unis",taille:"40 à 80 cm de carapace",poidsKg:80,vit:null,vie:70,
reg:"Carnivore",uicn:"VU",rar:4,
res:"La plus lourde tortue d'eau douce d'Amérique. Elle pêche avec un appât — un morceau de sa propre langue.",
f:[["Elle possède sur la langue un appendice rose et vermiforme qu'elle agite pour imiter un ver. Immobile, gueule ouverte, elle ressemble à un rocher moussu ; le poisson entre chercher le ver.","base"],
["Ce leurre change de couleur et se gorge de sang pour être plus visible. C'est l'un des rares cas de pêche à l'appât corporel chez un vertébré, avec la baudroie.","pointu"],
["Elle reste jusqu'à 50 minutes sous l'eau sans remonter, en abaissant son métabolisme. Elle peut passer des journées entières sans bouger.","pointu"],
["Sa morsure est puissante mais l'idée qu'elle sectionnerait un doigt d'un coup relève surtout de la légende locale : les mesures donnent environ 160 kg de force, moins que la mâchoire humaine sur les molaires. Le danger réel est la lacération par le bec tranchant, pas la puissance.","expert"],
["Elle vit jusqu'à 70 ans dans la nature et ne se reproduit qu'à partir de 12 à 20 ans, ce qui rend chaque adulte prélevé très difficile à remplacer. La demande pour la soupe de tortue a effondré ses populations au XXᵉ siècle.","pointu"]],
v:[["Leurre biologique","Appendice corporel imitant une proie pour attirer un prédateur à portée. Baudroie abyssale, tortue alligator, certaines vipères qui agitent leur queue comme un ver."]],
q:[["Comment la tortue alligator attire-t-elle les poissons ?",["Par une odeur","Avec un appendice de sa langue imitant un ver","Par des vibrations","En les poursuivant"],1,"Le leurre se gorge de sang pour être plus visible."],
["Que dit la mesure sur la puissance de sa morsure ?",["Elle sectionne un manche à balai","Environ 160 kg de force, moins que la mâchoire humaine sur les molaires","Elle est la plus forte du monde","On ne l'a jamais mesurée"],1,"Le vrai danger est la lacération par le bec, pas la puissance brute."]],
d:["records","camouflage"]},

/* ============ AMPHIBIENS ============ */

{id:"cecilie",nom:"Cécilie annelée",sci:"Siphonops annulatus",emo:"🪱",gr:"Amphibien",ord:"Gymnophiona",fam:"Siphonopidés",bio:"souterrain",
hab:"Sols forestiers meubles",rep:"Amérique du Sud",taille:"30 à 45 cm",poidsKg:0.05,vit:null,vie:13,
reg:"Carnivore",uicn:"LC",rar:5,
res:"Un amphibien sans pattes, aveugle et souterrain, dont les petits mangent la peau de leur mère — et qui pourrait bien être venimeux.",
f:[["Les gymnophiones forment le troisième ordre d'amphibiens, à côté des grenouilles et des salamandres. Ils sont environ 200 espèces, presque toutes souterraines, et restent le groupe de vertébrés terrestres le moins connu.","pointu"],
["La mère développe une peau épaisse et riche en graisses que ses petits arrachent et dévorent par lambeaux, à l'aide de dents temporaires spécialisées. Elle la régénère tous les trois jours. C'est la dermatophagie maternelle, filmée pour la première fois en 2006.","expert"],
["En 2020, on a découvert dans ses mâchoires des glandes ressemblant à celles d'un serpent venimeux et débouchant à la base des dents. Si le rôle venimeux se confirme, ce serait le premier amphibien à mordre pour envenimer — et une origine du venin buccal indépendante de celle des serpents.","expert"],
["Une étude de 2024 a montré que les sécrétions maternelles contiennent aussi des composés proches du lait : les petits réclament en émettant des sons, la mère répond. Chez un amphibien.","expert"],
["Deux tentacules rétractiles entre l'œil et la narine lui servent de sonde chimique dans le noir total. Ses yeux sont réduits et recouverts de peau ou d'os.","base"]],
v:[["Gymnophiones","Ordre d'amphibiens sans membres, au corps annelé, presque tous fouisseurs ou aquatiques. Le troisième grand groupe d'amphibiens, largement méconnu."]],
q:[["Qu'est-ce que la dermatophagie maternelle ?",["La mère mange ses petits","Les petits mangent la peau de leur mère, qu'elle régénère","Ils partagent une proie","Ils se nourrissent d'œufs"],1,"Filmée pour la première fois en 2006 ; la mère régénère sa peau tous les trois jours."],
["Qu'a-t-on découvert dans les mâchoires de la cécilie en 2020 ?",["Des dents à venin de serpent","Des glandes évoquant un appareil venimeux","Des capteurs thermiques","Des branchies"],1,"Ce serait une invention du venin buccal indépendante de celle des serpents."]],
d:["venins","parents","taxo"]},

{id:"pipa",nom:"Pipa du Suriname",sci:"Pipa pipa",emo:"🐸",gr:"Amphibien",ord:"Anura",fam:"Pipidés",bio:"riviere",
hab:"Eaux troubles et lentes",rep:"Amazonie, Guyanes",taille:"10 à 20 cm",poidsKg:0.16,vit:null,vie:8,
reg:"Carnivore",uicn:"LC",rar:5,
res:"Une grenouille plate comme une feuille morte, sans langue et sans voix, dont les petits sortent du dos de leur mère.",
f:[["Après une parade acrobatique en tonneau, le mâle presse les œufs sur le dos de la femelle. La peau gonfle et les enveloppe : chaque œuf s'enfonce dans une alvéole qui se referme. La mère porte alors une centaine de petites poches sous la peau.","base"],
["Le développement se fait entièrement dans le dos, sans stade têtard libre. Douze à vingt semaines plus tard, des grenouilles miniatures entièrement formées percent la peau et sortent une à une. La mère mue ensuite et retrouve un dos lisse.","pointu"],
["Elle n'a ni langue ni cordes vocales. Elle communique par des clics produits par un appareil osseux du larynx, et attrape ses proies par aspiration brutale, aidée de ses doigts avant terminés par de minuscules étoiles sensorielles.","expert"],
["Sa forme aplatie, sa couleur boueuse et son immobilité totale en font une feuille morte parfaite. Elle chasse à l'affût, sans jamais poursuivre.","pointu"],
["Ce mode de reproduction a longtemps été jugé si étrange qu'il a inspiré une phobie répandue sur internet, la trypophobie. Aucun animal n'a de trous dans le dos : ce sont des berceaux temporaires.","base"]],
v:[["Développement direct","Absence de stade larvaire libre : l'œuf donne directement un juvénile en miniature. Il affranchit l'espèce de la nécessité d'un point d'eau libre pour les têtards."]],
q:[["Où se développent les œufs de la pipa ?",["Dans l'eau","Dans des alvéoles sous la peau du dos de la mère","Dans la bouche du mâle","Dans un nid de mousse"],1,"Ils en sortent entièrement formés, sans stade têtard libre."],
["Comment la pipa attrape-t-elle ses proies ?",["Avec sa langue","Par aspiration brutale, aidée de ses doigts sensoriels","Avec ses pattes arrière","Elle filtre l'eau"],1,"Elle n'a ni langue ni cordes vocales."]],
d:["parents","camouflage"]},

{id:"rhinoderme-darwin",nom:"Rhinoderme de Darwin",sci:"Rhinoderma darwinii",emo:"🐸",gr:"Amphibien",ord:"Anura",fam:"Rhinodermatidés",bio:"foret",
hab:"Forêts humides tempérées",rep:"Chili, Argentine",taille:"3 cm",poidsKg:0.003,vit:null,vie:15,
reg:"Insectivore",uicn:"EN",rar:5,
res:"Le mâle avale ses propres têtards et les élève dans son sac vocal. Darwin l'a collectée lui-même en 1834.",
f:[["Le mâle surveille les œufs pendant environ trois semaines. Dès qu'il détecte le mouvement des embryons, il les gobe — jusqu'à vingt — et les fait glisser dans son sac vocal, l'organe qui lui sert normalement à chanter.","base"],
["Les têtards s'y développent six à huit semaines, nourris par des sécrétions de la paroi. Le mâle ne peut plus chanter et mange peu. Puis il recrache des grenouilles complètes par la bouche.","pointu"],
["Une seconde espèce, le rhinoderme de Darwin du Nord, n'a plus été observée depuis 1980 et est probablement éteinte. La cause principale est la chytridiomycose, une maladie fongique qui a fait disparaître ou décliner plus de 500 espèces d'amphibiens dans le monde — l'épidémie la plus destructrice jamais attribuée à un agent pathogène chez les vertébrés.","expert"],
["Ce champignon, Batrachochytrium dendrobatidis, s'attaque à la kératine de la peau. Comme les amphibiens respirent et régulent leurs sels par la peau, l'infection provoque un arrêt cardiaque. Sa diffusion mondiale est liée au commerce d'animaux.","expert"],
["Darwin a collecté cette grenouille au Chili pendant le voyage du Beagle. Personne à l'époque ne soupçonnait son mode de reproduction.","base"]],
v:[["Chytridiomycose","Maladie fongique de la peau des amphibiens, propagée mondialement par le commerce d'animaux. Première cause connue d'extinctions massives dues à un pathogène chez les vertébrés."]],
q:[["Où le rhinoderme mâle élève-t-il ses têtards ?",["Dans un nid","Dans son sac vocal","Sur son dos","Dans l'eau"],1,"Il ne peut plus chanter pendant les six à huit semaines de développement."],
["Qu'est-ce que la chytridiomycose ?",["Un parasite intestinal","Une maladie fongique de la peau ayant décimé plus de 500 espèces d'amphibiens","Une pollution chimique","Un virus des têtards"],1,"La peau étant leur organe respiratoire, l'infection est fatale."]],
d:["parents","retour"]},

{id:"protee",nom:"Protée anguillard",sci:"Proteus anguinus",emo:"🦎",gr:"Amphibien",ord:"Urodela",fam:"Protéidés",bio:"souterrain",
hab:"Rivières souterraines karstiques",rep:"Slovénie, Croatie, Bosnie",taille:"20 à 30 cm",poidsKg:0.02,vit:null,vie:100,
reg:"Carnivore",uicn:"VU",rar:5,
res:"Le « bébé dragon » des grottes des Balkans. Il vit un siècle dans le noir, jeûne dix ans, et peut rester immobile plusieurs années d'affilée.",
f:[["Il est aveugle : ses yeux régressent sous la peau dès les premières semaines. Sa peau est dépigmentée, rose pâle et translucide — d'où son surnom de « poisson humain » en slovène.","base"],
["Il vit environ 100 ans, une longévité stupéfiante pour un amphibien de 20 grammes, et n'est mature qu'à 15 ans. Il conserve ses branchies externes toute sa vie, comme l'axolotl : c'est aussi un néoténique.","pointu"],
["Il survit plus de dix ans sans manger en abaissant son métabolisme et en résorbant ses propres tissus. Dans une grotte, la nourriture arrive au hasard des crues : l'attente est la stratégie.","expert"],
["Une étude de suivi individuel a montré qu'un protée peut rester au même endroit sans bouger pendant sept ans. Le record documenté d'immobilité chez un vertébré — non pas par léthargie, mais parce que se déplacer ne rapporte rien.","expert"],
["Il détecte les champs électriques et magnétiques, s'oriente sans repère visuel, et perçoit les vibrations de l'eau par des organes latéraux. Le noir total ne le prive de rien.","pointu"]],
v:[["Troglobie","Espèce vivant exclusivement en milieu souterrain, généralement dépigmentée, aveugle, à métabolisme ralenti et à longévité élevée. Les mêmes traits réapparaissent chez des lignées sans lien : convergence des grottes."]],
q:[["Combien de temps un protée peut-il jeûner ?",["Un mois","Un an","Plus de dix ans","Trois jours"],2,"Il résorbe ses propres tissus en attendant la prochaine crue."],
["Qu'a montré le suivi individuel de protées ?",["Ils migrent","Un individu peut rester immobile sept ans","Ils chassent en groupe","Ils remontent en surface"],1,"Se déplacer ne rapporte rien dans une grotte : l'attente est la stratégie."]],
d:["extremes","records","convergence"]},

{id:"grenouille-wallace",nom:"Rainette volante de Wallace",sci:"Rhacophorus nigropalmatus",emo:"🐸",gr:"Amphibien",ord:"Anura",fam:"Rhacophoridés",bio:"jungle",
hab:"Canopée de forêt tropicale",rep:"Malaisie, Bornéo, Sumatra",taille:"8 à 10 cm",poidsKg:0.06,vit:null,vie:10,
reg:"Insectivore",uicn:"LC",rar:4,
res:"Une grenouille qui plane d'arbre en arbre sur ses mains et ses pieds palmés, décrite par le co-découvreur de la sélection naturelle.",
f:[["Ses quatre pattes portent des palmures très développées entre des doigts démesurés. En vol, elle les écarte au maximum : quatre petits parachutes plus des replis de peau le long des flancs.","base"],
["Elle plane sur plus de 15 m avec un angle de descente d'environ 45°, et oriente sa trajectoire en modifiant l'écartement de ses doigts. Elle atterrit sur un tronc grâce à de larges ventouses digitales.","pointu"],
["Alfred Russel Wallace, qui l'a décrite depuis Bornéo, avait formulé la sélection naturelle indépendamment de Darwin. C'est son manuscrit envoyé à Darwin en 1858 qui a précipité la publication de L'Origine des espèces l'année suivante.","expert"],
["Elle ne descend au sol que pour se reproduire : la femelle bat une mousse avec ses pattes au-dessus d'une flaque, y pond, et les têtards tombent dans l'eau à l'éclosion.","pointu"],
["Le vol plané est apparu de façon indépendante chez des grenouilles, des serpents, des lézards, des écureuils, des marsupiaux, des poissons et même des fourmis. Dans une forêt haute et dense, descendre puis remonter coûte plus cher que planer.","expert"]],
v:[["Sélection naturelle","Mécanisme par lequel les variantes qui survivent et se reproduisent le mieux dans un environnement donné deviennent plus fréquentes. Formulée indépendamment par Darwin et Wallace."]],
q:[["Comment la rainette de Wallace dirige-t-elle son vol plané ?",["Avec sa queue","En modifiant l'écartement de ses doigts palmés","Avec sa tête","Elle ne le dirige pas"],1,"Quatre parachutes réglables, plus des replis le long des flancs."],
["Qui était Alfred Russel Wallace ?",["Un explorateur sans lien avec la science","Le co-découvreur de la sélection naturelle","Un peintre naturaliste","Un botaniste"],1,"Son manuscrit de 1858 a précipité la publication de Darwin."]],
d:["convergence","records"]},

{id:"grenouille-poilue",nom:"Grenouille poilue",sci:"Trichobatrachus robustus",emo:"🐸",gr:"Amphibien",ord:"Anura",fam:"Arthroleptidés",bio:"riviere",
hab:"Torrents forestiers",rep:"Afrique centrale",taille:"11 cm",poidsKg:0.1,vit:null,vie:8,
reg:"Carnivore",uicn:"LC",rar:5,
res:"Menacée, elle se casse volontairement les os des doigts pour les faire sortir à travers sa peau, en guise de griffes.",
f:[["Ses griffes ne sont pas en kératine comme celles des autres vertébrés : ce sont des os. Chaque doigt contient un petit os pointu relié par un tendon à un muscle.","pointu"],
["En contractant ce muscle, la grenouille arrache l'os de son point d'ancrage, le fait pivoter et le pousse à travers le coussinet du doigt. La peau est perforée de l'intérieur. Aucun autre vertébré ne s'automutile pour s'armer.","expert"],
["On ignore encore comment la blessure se referme, et si l'os se rétracte de lui-même. Chez un animal qui régénère mal, c'est une énigme qui intéresse la biologie des tissus.","expert"],
["Les « poils » du mâle en période de reproduction sont des papilles de peau richement irriguées, remplies de vaisseaux sanguins. Elles augmentent la surface d'échange gazeux et lui permettent de rester longtemps immergé à surveiller les œufs sans remonter respirer.","pointu"],
["Elle est chassée et consommée dans plusieurs régions du Cameroun. Les chasseurs la tuent à distance, avec de longues lances — précisément à cause des griffes.","base"]],
v:[["Autotomie défensive","Perte ou destruction volontaire d'une partie de son propre corps pour survivre : queue du lézard, patte du criquet, bras de l'étoile de mer. Ici, c'est l'inverse : l'automutilation sert à attaquer."]],
q:[["De quoi sont faites les griffes de la grenouille poilue ?",["De kératine","D'os, poussés à travers la peau","De cartilage","D'écailles durcies"],1,"Elle perfore son propre coussinet de l'intérieur pour les sortir."],
["À quoi servent les « poils » du mâle ?",["À séduire","À augmenter la surface d'échange gazeux pour rester immergé","À se camoufler","À sentir l'eau"],1,"Des papilles de peau richement irriguées, pendant la garde des œufs."]],
d:["extremes","parents"]},

/* ============ POISSONS ============ */

{id:"poisson-clown",nom:"Poisson-clown à trois bandes",sci:"Amphiprion ocellaris",emo:"🐠",gr:"Poisson",ord:"Perciformes",fam:"Pomacentridés",bio:"ocean",
hab:"Anémones de récif corallien",rep:"Indo-Pacifique",taille:"8 à 11 cm",poidsKg:0.03,vit:null,vie:10,
reg:"Omnivore",uicn:"LC",rar:2,
res:"Tous naissent mâles. Quand la femelle du groupe meurt, c'est son partenaire qui devient femelle — ce qui rend l'intrigue du film assez différente.",
f:[["Chaque anémone abrite un couple dominant et quelques mâles subordonnés. Le seul individu à se reproduire est la femelle, la plus grosse ; le mâle dominant est le deuxième.","base"],
["Tous les poissons-clowns naissent mâles. À la mort de la femelle, le mâle dominant change de sexe et prend sa place, et le subordonné le plus gros devient le nouveau mâle reproducteur. C'est de l'hermaphrodisme protandre, et c'est irréversible.","pointu"],
["Dans Le Monde de Nemo, la mère est mangée au début. Biologiquement, le père serait donc devenu une femelle, et Nemo aurait fini par s'accoupler avec lui. Un exemple utile de ce que la fiction fait à la biologie.","expert"],
["Il ne craint pas les cellules urticantes de l'anémone grâce à un mucus particulier, dont la composition l'empêche de déclencher les harpons. Une part de cette protection est acquise : le jeune poisson danse en s'y frottant progressivement.","expert"],
["L'échange est équilibré : l'anémone offre un abri inviolable, le poisson la défend des poissons-papillons qui la broutent, oxygène l'eau autour d'elle et la nourrit de ses déchets. Une anémone habitée grandit plus vite.","pointu"]],
v:[["Hermaphrodisme protandre","Changement de sexe au cours de la vie, du mâle vers la femelle. L'inverse — protogyne — existe aussi, chez les mérous et les labres."]],
q:[["Que se passe-t-il quand la femelle d'un groupe de poissons-clowns meurt ?",["Un mâle arrive de l'extérieur","Le mâle dominant devient femelle","Le groupe se disperse","Rien ne change"],1,"Un changement de sexe irréversible, appelé protandrie."],
["Comment le poisson-clown supporte-t-il l'anémone ?",["Il est immunisé de naissance","Un mucus particulier empêche le déclenchement des harpons","Ses écailles sont épaisses","Il évite les tentacules"],1,"Une protection en partie acquise, par frottements progressifs."]],
d:["symbiose","parents"]},

{id:"fugu",nom:"Fugu (tétrodon tigré)",sci:"Takifugu rubripes",emo:"🐡",gr:"Poisson",ord:"Tetraodontiformes",fam:"Tétraodontidés",bio:"ocean",
hab:"Fonds côtiers",rep:"Mers du Japon et de Chine",taille:"40 à 70 cm",poidsKg:5,vit:null,vie:10,
reg:"Carnivore",uicn:"NT",rar:4,
res:"Son poison est 1 200 fois plus toxique que le cyanure. Et il ne le fabrique pas.",
f:[["La tétrodotoxine bloque les canaux sodium des nerfs : la victime reste parfaitement consciente pendant que ses muscles se paralysent, y compris le diaphragme. Il n'existe aucun antidote ; le seul traitement est la ventilation artificielle jusqu'à élimination.","base"],
["Le poisson ne synthétise pas ce poison. Il l'accumule à partir de bactéries présentes dans sa chaîne alimentaire. Élevé en bassin avec une nourriture contrôlée, un fugu devient totalement inoffensif — des élevages japonais en produisent aujourd'hui.","expert"],
["Il est immunisé contre son propre poison par une mutation de ses canaux sodium, qui empêche la toxine de s'y fixer. La même solution que la mangouste face au cobra, sur une molécule différente.","expert"],
["Il ne se gonfle pas d'air mais d'eau, en remplissant un estomac extensible. Sa peau, dépourvue d'écailles et très élastique, peut tripler son volume. Il n'a pas de côtes, qui gêneraient l'expansion.","pointu"],
["Son génome, l'un des plus compacts de tous les vertébrés — huit fois plus petit que le nôtre pour un nombre de gènes comparable — a servi de référence pour repérer les gènes dans l'ADN humain.","expert"]],
v:[["Tétrodotoxine","Neurotoxine bloquant les canaux sodium, d'origine bactérienne. On la retrouve chez des animaux sans lien de parenté : fugu, pieuvre à anneaux bleus, tritons, certains crabes — tous la récupèrent, aucun ne la fabrique."]],
q:[["Le fugu fabrique-t-il son poison ?",["Oui, dans son foie","Non : il l'accumule via des bactéries de son alimentation","Oui, dans sa peau","Il le fabrique en cas de stress"],1,"Élevé avec une nourriture contrôlée, il devient inoffensif."],
["Avec quoi le fugu se gonfle-t-il ?",["De l'air","De l'eau","De gaz digestif","De graisse"],1,"Un estomac extensible, une peau sans écailles et aucune côte pour gêner."]],
d:["venins","records"]},

{id:"tetrodon-cercles",nom:"Tétrodon à points blancs",sci:"Torquigener albomaculosus",emo:"🐡",gr:"Poisson",ord:"Tetraodontiformes",fam:"Tétraodontidés",bio:"ocean",
hab:"Fonds sableux",rep:"Sud du Japon",taille:"12 cm",poidsKg:0.05,vit:null,vie:5,
reg:"Carnivore",uicn:"DD",rar:5,
res:"Un poisson de douze centimètres qui sculpte dans le sable un cercle de deux mètres, parfaitement géométrique, pour séduire.",
f:[["En 1995, des plongeurs japonais découvrent au fond de l'eau des cercles géométriques de 2 m, ornés de rayons réguliers. L'auteur reste inconnu vingt ans : ce sont les « cercles sous-marins », l'un des mystères marins les plus commentés de l'époque.","base"],
["En 2011, on filme enfin le sculpteur : un tétrodon mâle de 12 cm, qui travaille sept à neuf jours d'affilée, jour et nuit. Il creuse les sillons en nageant sur le flanc, décore les crêtes de fragments de coquillages et trie les grains de sable les plus fins vers le centre. L'espèce n'a été formellement décrite qu'en 2014.","pointu"],
["Les rayons ne sont pas décoratifs : ils cassent les courants de fond et concentrent au centre les sédiments les plus fins, où la femelle pondra. C'est une construction fonctionnelle autant qu'un signal.","expert"],
["La femelle inspecte le cercle et décide. S'il est retenu, elle pond au centre ; le mâle garde les œufs pendant six jours, puis abandonne l'ouvrage. Il ne réutilise jamais un cercle : il en recommence un ailleurs.","expert"],
["L'histoire est un cas d'école : une trace observée pendant vingt ans avant qu'on n'identifie l'animal, puis l'animal décrit trois ans après avoir été filmé. On peut connaître l'œuvre bien avant l'auteur.","base"]],
v:[["Comportement d'édification","Construction élaborée servant de signal ou de nurserie : berceau du jardinier, nid du cichlidé, cercle du tétrodon. C'est un phénotype étendu — l'ouvrage prolonge le corps de l'animal."]],
q:[["Combien de temps le tétrodon met-il à sculpter son cercle ?",["Une heure","Sept à neuf jours, jour et nuit","Un mois","Quelques minutes"],1,"Pour un poisson de 12 cm et un cercle de 2 m."],
["À quoi servent les rayons du cercle ?",["Uniquement à décorer","À casser les courants et concentrer le sable fin au centre","À piéger des proies","À délimiter un territoire"],1,"Une construction fonctionnelle : c'est là que la femelle pondra."]],
d:["outils","records"]},

{id:"poisson-perroquet",nom:"Poisson-perroquet à bosse",sci:"Bolbometopon muricatum",emo:"🐠",gr:"Poisson",ord:"Perciformes",fam:"Scaridés",bio:"ocean",
hab:"Récifs coralliens",rep:"Indo-Pacifique",taille:"1,3 m",poidsKg:75,vit:null,vie:40,
reg:"Corallivore",uicn:"VU",rar:4,
res:"Il mange le corail, digère les algues et recrache la roche. Une bonne partie du sable des plages tropicales est passée par un poisson-perroquet.",
f:[["Ses dents sont soudées en un bec puissant, d'où son nom. Il arrache des morceaux de corail vivant, et une seconde mâchoire située dans la gorge les broie en poudre.","base"],
["Il digère les algues symbiotiques du corail et rejette le calcaire sous forme de sable fin. Un gros individu produit jusqu'à une centaine de kilos de sable par an. Les plages blanches des atolls sont en grande partie des déjections de poissons-perroquets.","pointu"],
["La nuit, beaucoup d'espèces sécrètent un cocon de mucus qui les enveloppe entièrement. Il masque leur odeur des prédateurs nocturnes et bloque les parasites — une moustiquaire fabriquée chaque soir et abandonnée chaque matin.","expert"],
["Il change de sexe et de livrée au cours de sa vie : les femelles peuvent devenir mâles dominants, avec des couleurs si différentes qu'on a longtemps classé les deux formes comme des espèces distinctes.","pointu"],
["En broutant, il nettoie les surfaces des algues qui étoufferaient les jeunes coraux. Sur les récifs surpêchés en poissons-perroquets, les algues prennent le dessus et la récupération après un blanchissement devient beaucoup plus lente.","expert"]],
v:[["Bioérosion","Érosion des roches par des êtres vivants. Sur un récif, les poissons-perroquets et les oursins en sont les principaux moteurs — et les producteurs de sable."]],
q:[["D'où vient une grande partie du sable des plages tropicales ?",["De l'érosion des roches","Des déjections des poissons-perroquets","Des coquillages broyés","Du vent"],1,"Jusqu'à une centaine de kilos par an pour un gros individu."],
["À quoi sert le cocon de mucus nocturne ?",["À respirer","À masquer l'odeur des prédateurs et bloquer les parasites","À flotter","À se réchauffer"],1,"Une moustiquaire fabriquée chaque soir, abandonnée chaque matin."]],
d:["symbiose","records"]},

{id:"periophtalme",nom:"Périophtalme",sci:"Periophthalmus barbarus",emo:"🐟",gr:"Poisson",ord:"Gobiiformes",fam:"Gobiidés",bio:"riviere",
hab:"Vasières de mangrove",rep:"Afrique de l'Ouest, Indo-Pacifique",taille:"15 à 25 cm",poidsKg:0.06,vit:null,vie:5,
reg:"Carnivore",uicn:"LC",rar:3,
res:"Un poisson qui passe plus de temps hors de l'eau que dedans, qui grimpe aux racines et qui doit remplir sa bouche d'eau pour manger.",
f:[["Il respire par la peau, la paroi de sa bouche et de sa gorge, à condition de rester humide. Il se roule régulièrement dans la vase pour se réhumidifier, comme on recharge une batterie.","base"],
["Il emporte une réserve d'eau dans ses chambres branchiales, qu'il renouvelle à chaque bain. Ses joues gonflées ne sont pas de la graisse : c'est sa bouteille de plongée à l'envers.","pointu"],
["Il ne peut pas avaler à l'air libre : sans eau, la nourriture ne descend pas. Il garde donc une gorgée d'eau en bouche, la projette sur sa proie posée sur la vase, puis réaspire le tout. Il transporte son milieu aquatique pour pouvoir manger à terre.","expert"],
["Il se déplace en s'appuyant sur ses nageoires pectorales musclées, en une démarche de béquilles, et saute jusqu'à 60 cm en repliant sa queue comme un ressort. Il grimpe aux racines de palétuviers.","pointu"],
["Le mâle creuse un terrier en Y dans la vase anoxique et y transporte des bouchées d'air pour oxygéner les œufs. Il fait des allers-retours pendant des jours : sans lui, la ponte s'asphyxie.","expert"]],
v:[["Respiration cutanée et bucco-pharyngée","Échanges gazeux par la peau et les muqueuses de la bouche. Elle exige des surfaces humides et bien irriguées, et limite la taille de l'animal."]],
q:[["Pourquoi le périophtalme garde-t-il de l'eau en bouche ?",["Pour respirer seulement","Il ne peut pas avaler à sec : il projette l'eau sur sa proie et réaspire","Pour se rafraîchir","Pour attirer des proies"],1,"Il transporte son milieu aquatique pour manger à terre."],
["Que transporte le mâle dans son terrier ?",["De la nourriture","Des bouchées d'air pour oxygéner les œufs","De la vase","Des algues"],1,"La vase est anoxique : sans ces allers-retours, la ponte s'asphyxie."]],
d:["extremes","parents"]},

{id:"myxine",nom:"Myxine",sci:"Myxine glutinosa",emo:"🐍",gr:"Poisson",ord:"Myxiniformes",fam:"Myxinidés",bio:"abysse",
hab:"Fonds vaseux profonds",rep:"Atlantique nord",taille:"40 à 60 cm",poidsKg:0.5,vit:null,vie:40,
reg:"Charognard",uicn:"LC",rar:5,
res:"Sans mâchoires, sans vertèbres, sans écailles et sans estomac — mais capable de transformer un seau d'eau de mer en gelée en quelques secondes.",
f:[["Agressée, elle libère par une centaine de pores latéraux un mucus qui, au contact de l'eau, se déploie en une masse gélatineuse pouvant atteindre 10 000 fois son volume initial. Un prédateur qui la mord se retrouve les branchies obstruées et la relâche.","base"],
["Ce mucus contient des fils de protéines de 15 cm, plus fins qu'un cheveu et comparables à la soie d'araignée en résistance. Des laboratoires militaires et textiles cherchent à les reproduire pour fabriquer des fibres sans pétrole.","expert"],
["Pour se dégager de sa propre gelée, elle fait un nœud avec son corps et le fait coulisser de la tête à la queue. Elle utilise le même nœud pour prendre appui et arracher un morceau de chair d'une carcasse.","pointu"],
["Elle n'a ni mâchoires, ni vertèbres, ni nageoires paires, ni estomac. Elle absorbe aussi des nutriments directement par la peau, en s'enfouissant dans une carcasse. Les myxines et les lamproies sont les derniers vertébrés sans mâchoires — un plan d'organisation vieux de plus de 500 millions d'années.","expert"],
["Elle a quatre cœurs et un crâne de cartilage sans colonne vertébrale, ce qui en fait un cas limite pour la définition même de « vertébré ».","pointu"]],
v:[["Agnathes","Vertébrés sans mâchoires. Ils dominaient les mers il y a 500 millions d'années ; il n'en reste que les myxines et les lamproies."]],
q:[["De combien le mucus de la myxine se déploie-t-il ?",["Il double","Environ 10 000 fois son volume","De moitié","Il ne se déploie pas"],1,"Assez pour obstruer les branchies du prédateur qui la mord."],
["Comment la myxine se débarrasse-t-elle de sa propre gelée ?",["Elle mue","Elle fait un nœud avec son corps et le fait coulisser","Elle la mange","Elle attend"],1,"Le même nœud lui sert d'appui pour arracher de la chair."]],
d:["taxo","abysses","records"]},

{id:"requin-marteau",nom:"Grand requin-marteau",sci:"Sphyrna mokarran",emo:"🦈",gr:"Poisson",ord:"Carcharhiniformes",fam:"Sphyrnidés",bio:"ocean",
hab:"Récifs et eaux côtières tropicales",rep:"Mondiale, eaux chaudes",taille:"3,5 à 6 m",poidsKg:450,vit:40,vie:40,
reg:"Carnivore",uicn:"CR",rar:4,
res:"Sa tête en marteau n'est pas une bizarrerie : c'est une antenne, un gouvernail et une paire de jumelles, tout à la fois.",
f:[["Le céphalofoil — la tête en T — étale ses ampoules de Lorenzini sur une surface bien plus large. Le requin balaie le sable de gauche à droite comme un détecteur de métaux et repère les raies enfouies à leur seul champ électrique.","pointu"],
["Ses yeux, placés aux extrémités, lui donnent un champ visuel vertical de 360° et une vision binoculaire frontale supérieure à celle des autres requins — l'inverse de ce qu'on supposait avant les mesures de 2009, qui prédisaient un angle mort central.","expert"],
["Il nage souvent incliné à 90°, sur le flanc. Une étude de 2016 a montré que cette posture bizarre réduit sa consommation d'énergie d'environ 10 % : sa grande nageoire dorsale devient une aile portante. Il nage sur le côté parce que c'est moins cher.","expert"],
["Il maintient la raie au sol avec sa tête, comme avec un pied, avant de la mordre. Il est aussi l'un des rares requins à chasser des raies venimeuses, et on retrouve régulièrement des dards plantés dans sa gueule sans effet apparent.","pointu"],
["Il est classé en danger critique. Il figure parmi les espèces dont les ailerons sont les plus recherchés, et il supporte très mal la capture : une forte proportion des individus relâchés meurent de stress après avoir été remontés.","base"]],
v:[["Céphalofoil","Extension latérale de la tête des requins-marteaux. Elle sert à la fois de surface sensorielle, de plan de sustentation et de support pour des yeux très écartés."]],
q:[["Que permet d'abord le céphalofoil ?",["De frapper ses proies","D'étaler ses capteurs électriques sur une large surface","De nager plus vite","De filtrer l'eau"],1,"Un détecteur de métaux vivant, balayé au-dessus du sable."],
["Pourquoi le requin-marteau nage-t-il souvent sur le flanc ?",["Pour voir le fond","Ça réduit sa dépense d'énergie d'environ 10 %","Pour chasser","À cause du courant"],1,"Sa dorsale devient une aile portante."]],
d:["sens","records"]},

{id:"macropinna",nom:"Poisson à tête transparente",sci:"Macropinna microstoma",emo:"🐟",gr:"Poisson",ord:"Argentiniformes",fam:"Opisthoproctidés",bio:"abysse",
hab:"Zone crépusculaire, 400 à 800 m",rep:"Pacifique nord",taille:"15 cm",poidsKg:0.02,vit:null,vie:10,
reg:"Carnivore",uicn:"DD",rar:5,
res:"Son crâne est un dôme transparent rempli de liquide, dans lequel ses yeux tournent. Il a fallu cinquante ans pour s'en apercevoir.",
f:[["Décrit en 1939 à partir de spécimens remontés au chalut, il a longtemps été représenté avec deux yeux fixes tournés vers le haut. Ce n'est qu'en 2004, filmé vivant par un sous-marin téléguidé, qu'on a vu l'essentiel : un dôme transparent intact coiffe sa tête. La remontée le faisait éclater à chaque fois.","expert"],
["Ce que l'on prend pour ses yeux sont ses narines. Ses vrais yeux sont les deux cylindres verts à l'intérieur du dôme — et ils pivotent : orientés vers le haut pour repérer les silhouettes à contre-jour, ils basculent vers l'avant quand il attaque, pour viser.","expert"],
["Ses yeux tubulaires captent le maximum de lumière résiduelle, au prix du champ de vision. Le pigment vert filtre la lumière du soleil et lui permet de distinguer la bioluminescence des proies malgré elle.","pointu"],
["Il vole probablement une partie de sa nourriture aux siphonophores, ces longues colonies urticantes du large. Le dôme protégerait ses yeux de leurs cellules urticantes pendant l'opération.","pointu"],
["Il est un rappel utile : pendant soixante-cinq ans, tous les manuels ont reproduit un animal abîmé par la méthode de capture. On dessinait un cadavre déformé en croyant dessiner un poisson.","base"]],
v:[["Yeux tubulaires","Yeux en forme de cylindre, très sensibles mais à champ réduit, fréquents dans la zone crépusculaire. Ils maximisent la captation de lumière au détriment de la vision périphérique."]],
q:[["Qu'a-t-on découvert en filmant le macropinna vivant en 2004 ?",["Il est aveugle","Sa tête est coiffée d'un dôme transparent, détruit par la remontée au chalut","Il vit en banc","Il est bioluminescent"],1,"Pendant 65 ans, on a dessiné un spécimen abîmé par la capture."],
["Que sont les deux points sombres à l'avant de sa tête ?",["Ses yeux","Ses narines","Ses branchies","Des organes lumineux"],1,"Ses vrais yeux sont les cylindres verts qui pivotent dans le dôme."]],
d:["abysses","sens","records"]},

{id:"anguille-europeenne",nom:"Anguille européenne",sci:"Anguilla anguilla",emo:"🐍",gr:"Poisson",ord:"Anguilliformes",fam:"Anguillidés",bio:"riviere",
hab:"Rivières, étangs, puis océan",rep:"Europe, Afrique du Nord, mer des Sargasses",taille:"60 à 150 cm",poidsKg:2,vit:null,vie:20,
reg:"Carnivore",uicn:"CR",rar:5,
res:"Personne n'a jamais vu deux anguilles se reproduire. Aristote pensait qu'elles naissaient de la boue ; Freud a passé sa jeunesse à leur chercher des testicules, sans succès.",
f:[["Elle traverse l'Atlantique sur 5 000 à 6 000 km pour pondre dans la mer des Sargasses, puis meurt. Les larves, transparentes et en forme de feuille, dérivent trois ans jusqu'aux côtes européennes.","base"],
["Aucun œuf d'anguille européenne n'a jamais été observé dans la nature, et aucun adulte n'a jamais été vu se reproduire. On déduit le lieu de ponte de la répartition des plus petites larves, pas d'une observation directe. C'est l'un des plus vieux problèmes ouverts de la zoologie.","expert"],
["Aristote croyait qu'elles naissaient spontanément de la vase, faute d'y trouver le moindre organe reproducteur. Le jeune Sigmund Freud, à 19 ans, en a disséqué environ 400 à Trieste pour chercher leurs testicules — sans rien trouver de concluant. On sait aujourd'hui que les organes ne se développent qu'au départ vers les Sargasses.","expert"],
["Elle change quatre fois de forme et de couleur au cours de sa vie : larve leptocéphale transparente, civelle, anguille jaune, puis anguille argentée dont les yeux grossissent et le tube digestif se résorbe avant le grand départ.","pointu"],
["Sa population a chuté de plus de 90 % depuis les années 1980 — barrages, parasites introduits, pêche de civelles pour l'aquaculture asiatique. Elle est classée en danger critique. Un animal dont on ignore encore comment il se reproduit est en train de disparaître.","base"]],
v:[["Catadromie","Cycle de vie où l'animal grandit en eau douce et se reproduit en mer. C'est l'inverse de l'anadromie du saumon."]],
q:[["Où pond l'anguille européenne ?",["Dans les rivières","Dans la mer des Sargasses","En Méditerranée","Sur les côtes"],1,"Déduit de la répartition des plus petites larves — jamais observé directement."],
["Qu'a fait Freud à 19 ans avec des anguilles ?",["Il les a élevées","Il en a disséqué 400 pour chercher leurs testicules, sans succès","Il les a peintes","Il les a marquées"],1,"Les organes ne se développent qu'au moment du départ vers les Sargasses."]],
d:["migrations","taxo","records"]},

{id:"arapaima",nom:"Arapaïma",sci:"Arapaima gigas",emo:"🐟",gr:"Poisson",ord:"Osteoglossiformes",fam:"Ostéoglossidés",bio:"riviere",
hab:"Fleuves et lacs amazoniens",rep:"Bassin amazonien",taille:"2 à 3 m",poidsKg:200,vit:null,vie:20,
reg:"Carnivore",uicn:"DD",rar:4,
res:"Un poisson qui se noierait sous l'eau, et dont les écailles arrêtent les dents de piranha. Sa structure est étudiée pour fabriquer des gilets pare-balles.",
f:[["Sa vessie natatoire est tapissée de tissu pulmonaire : c'est un vrai poumon. Il doit remonter respirer toutes les 10 à 20 minutes, avec un souffle sonore. Empêché de le faire, il se noie.","base"],
["Ses écailles ont une architecture en deux couches : une surface minéralisée très dure, et un socle de collagène disposé en lamelles orientées différemment d'une couche à l'autre. La couche dure fissure sous la dent, mais la fissure est déviée et absorbée par le socle souple. Le principe est étudié pour concevoir des armures composites.","expert"],
["Cette résistance a une raison précise : il vit dans les mêmes eaux que les piranhas, et pendant la saison sèche il se retrouve enfermé avec eux dans des mares réduites.","pointu"],
["Les deux parents gardent les alevins et sécrètent par la tête une substance blanchâtre riche en hormones, que les jeunes viennent brouter. Le banc reste collé à cette source pendant des mois.","expert"],
["Sa nécessité de respirer en surface le rend facile à harponner : il a disparu de nombreux tronçons de l'Amazone. Là où des quotas gérés par les communautés locales ont été instaurés, les populations ont été multipliées par dix en une décennie — un des exemples les plus nets de pêche durable réussie.","pointu"]],
v:[["Matériau composite","Assemblage de couches aux propriétés différentes — dure et fragile, souple et tenace — dont l'ensemble résiste mieux que chacune séparément. Écailles d'arapaïma, nacre, os, club de la squille."]],
q:[["Que se passe-t-il si un arapaïma ne peut pas remonter en surface ?",["Rien","Il se noie","Il hiberne","Il change de couleur"],1,"Sa vessie natatoire est un vrai poumon."],
["Pourquoi ses écailles résistent-elles aux dents de piranha ?",["Elles sont très épaisses","Une couche dure fissure, un socle de collagène dévie la fissure","Elles sont mobiles","Elles sont toxiques"],1,"Un composite étudié aujourd'hui pour concevoir des armures."]],
d:["records","parents"]},

{id:"requin-pelerin",nom:"Requin pèlerin",sci:"Cetorhinus maximus",emo:"🦈",gr:"Poisson",ord:"Lamniformes",fam:"Cétorhinidés",bio:"ocean",
hab:"Eaux tempérées de surface",rep:"Mondiale, mers tempérées",taille:"7 à 10 m",poidsKg:5000,vit:6,vie:50,
reg:"Planctonophage",uicn:"EN",rar:4,
res:"Le deuxième plus grand poisson du monde. Il filtre 2 000 tonnes d'eau par heure, gueule ouverte, à l'allure d'un promeneur.",
f:[["Il nage bouche grande ouverte à environ 4 km/h et filtre jusqu'à 2 000 m³ d'eau par heure avec ses branchiospines, des peignes de kératine qui retiennent le zooplancton.","base"],
["Ses fentes branchiales font presque le tour de sa tête. Vu de face, il ressemble à un tunnel.","base"],
["Des balises ont révélé qu'il ne disparaît pas en hiver comme on le croyait : il descend à plus de 1 000 m et traverse l'équateur. Un individu marqué au large de l'Angleterre a été retrouvé au Brésil.","pointu"],
["Les carcasses échouées, une fois la mâchoire et les nageoires décomposées, laissent un squelette au long cou et à la petite tête qui a nourri de nombreux signalements de « monstres marins ». La carcasse de Zuiyō-maru, remontée par un chalutier japonais en 1977 et présentée comme un plésiosaure, était un requin pèlerin — les analyses de protéines l'ont établi.","expert"],
["Massivement pêché pour l'huile de son foie, qui peut représenter un quart de son poids, il n'a été protégé qu'après l'effondrement de ses populations. Sa maturité tardive et sa gestation, estimée entre un et trois ans, rendent son rétablissement très lent.","pointu"]],
v:[["Branchiospine","Peigne rigide bordant les arcs branchiaux, qui filtre les particules de l'eau. Requins pèlerins, requins-baleines et baleines à fanons ont chacun inventé leur version du filtre."]],
q:[["Comment se nourrit le requin pèlerin ?",["Il chasse des phoques","Il filtre le zooplancton en nageant bouche ouverte","Il broute des algues","Il fouille le fond"],1,"Jusqu'à 2 000 m³ d'eau filtrés par heure."],
["Qu'était la carcasse de Zuiyō-maru, présentée comme un plésiosaure ?",["Un cachalot","Un requin pèlerin décomposé","Un calmar géant","Une baleine"],1,"Les analyses de protéines l'ont établi — la décomposition crée un faux long cou."]],
d:["records","convergence"]},

{id:"protoptere",nom:"Protoptère",sci:"Protopterus annectens",emo:"🐟",gr:"Poisson",ord:"Lepidosireniformes",fam:"Protoptéridés",bio:"riviere",
hab:"Mares temporaires et marais",rep:"Afrique subsaharienne",taille:"80 à 100 cm",poidsKg:4,vit:null,vie:20,
reg:"Carnivore",uicn:"LC",rar:5,
res:"Quand sa mare s'assèche, il se fabrique un cocon de mucus dans la boue et attend la pluie — parfois quatre ans.",
f:[["Il possède de vrais poumons et doit respirer de l'air : maintenu sous l'eau, il se noie. Ses branchies sont réduites et insuffisantes.","base"],
["À l'assèchement, il s'enfonce dans la vase, sécrète un cocon de mucus qui durcit et ne laisse qu'un tube pour respirer. Son métabolisme chute à un soixantième de la normale et il consomme ses propres muscles. C'est l'estivation : jusqu'à quatre ans documentés en laboratoire.","expert"],
["Il transforme ses déchets azotés en urée, moins toxique, et l'accumule dans son sang à des concentrations qui tueraient la plupart des vertébrés. À la première pluie, il se réveille en quelques heures et évacue tout.","expert"],
["Les dipneustes sont, avec le cœlacanthe, les poissons les plus proches des tétrapodes — donc de nous. Le protoptère « marche » d'ailleurs au fond de l'eau sur ses nageoires filiformes, en alternant droite et gauche comme une salamandre. Cette démarche a été filmée en 2011 chez une espèce voisine et éclaire la sortie des eaux.","expert"],
["Son génome est l'un des plus grands du vivant animal, une quarantaine de fois le nôtre — un record chez les vertébrés séquencés.","pointu"]],
v:[["Estivation","Léthargie de survie pendant la saison chaude et sèche, symétrique de l'hibernation. Elle suppose de tenir sans eau, sans nourriture et sans évacuer ses déchets."]],
q:[["Que fait le protoptère quand sa mare s'assèche ?",["Il migre","Il s'enferme dans un cocon de mucus dans la vase","Il pond et meurt","Il respire par la peau"],1,"L'estivation : jusqu'à quatre ans documentés."],
["Pourquoi les dipneustes intéressent-ils autant les chercheurs ?",["Ils sont comestibles","Ils comptent parmi les poissons les plus proches des tétrapodes","Ils sont très rares","Ils vivent très vieux"],1,"Leur démarche sur les nageoires éclaire la sortie des eaux."]],
d:["extremes","taxo","records"]}

]);
